const course: DeepCourse = {"slug":"becoming-an-ops-lead","title":"Becoming an Operations Lead.","premium":true,"previewCount":3,"chunks":[{"kind":"html","value":"<section class=\"px-5 pt-28 md:px-8 md:pt-40\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Ops · Pro</p><h1 class=\"display-lg mt-4\">Becoming an Operations Lead<span class=\"dot\" aria-hidden=\"true\">.</span></h1><p class=\"lede mt-5 max-w-xl\">Stop being the person who does the tasks. Become the person who owns whether the tasks happen at all.</p><div class=\"mt-8\"><div class=\"flex flex-wrap items-center gap-2.5\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Premium course</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">10 modules</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">5h 1m of reading and doing</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">8 portfolio pieces</span></div><p class=\"mt-4 mb-2 text-[0.8125rem] text-muted\">Course content is based on active job listings and industry hiring patterns. These are practical guides, not formal certifications.</p></div></div></section><nav aria-label=\"Course sections\" class=\"sticky top-16 z-20 border-b border-line bg-paper/90 backdrop-blur-md\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-6xl\"><ul class=\"-mx-1 flex gap-1 overflow-x-auto py-2.5 [scrollbar-width:none] [&amp;::-webkit-scrollbar]:hidden\"><li><a href=\"#the-job\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">The job</a></li><li><a href=\"#tools\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Tools</a></li><li><a href=\"#modules\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Modules</a></li><li><a href=\"#rates\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Rates</a></li><li><a href=\"#first-client\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">First client</a></li><li><a href=\"#quiz\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Quiz</a></li><li><a href=\"#glossary\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Glossary</a></li><li><a href=\"#red-flags\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Red flags</a></li><li><a href=\"#faq\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">FAQ</a></li></ul></div></nav><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"the-job\" class=\"scroll-mt-32\"><div class=\"space-y-5\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">There is a ceiling on doing. You can be the fastest, most reliable VA a founder has ever had and still be paid for hours, because hours are what you are selling. The move out of that is not more skill at the tasks. It is taking responsibility for outcomes and for other people's work.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">A VA on r/buhaydigital put the whole career question in one line: do not make VA your ceiling, it is a starting point. In the same thread someone described running three clients while training a small team to deliver, earning around ₱400,000 a month and keeping ₱300,000 after paying them, with the explicit goal of managing rather than doing. Neither of those people got there by typing faster.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">This track runs on one fictional business: Wilder and Co, a twelve-person home-services marketing agency in Ohio, where you started as a VA eighteen months ago. Over ten modules you will map their operations, build the SOP library, define the metrics, hire and manage two contractors, run the operating rhythm, report upward, and price yourself as the person who runs the system.</p></div><dl class=\"mt-10 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card shadow-tile\"><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Also posted as</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Operations manager, OBM, chief of staff, delivery manager, integrator</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">The shift</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">From \"did you get my message\" to \"here is the number and what I am doing about it\"</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Core loop</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Map, document, measure, delegate, review</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">What you stop doing</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Being the fastest hands. That is now somebody else's job and your responsibility</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Hardest part</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Holding someone else to a standard when you could just do it yourself in ten minutes</dd></div></dl></section><section class=\"mt-16\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What a shift actually looks like</h2><ol class=\"mt-6 space-y-0\"><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Start of shift</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Read the numbers before the messages</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Dashboard first. If you open Slack first you spend the day inside other people's priorities.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">First hour</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Unblock the team</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Anything stopping someone else from working gets handled before anything that only stops you.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Mid-shift</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">One improvement, not ten</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">A process fixed properly this week beats five patched badly. Pick the one with the biggest leak.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Afternoon</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Reviews and quality checks</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Sample the team's output against the SOP. Not all of it, and not none of it.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Twice weekly</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">One-to-ones, 20 minutes</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Their blockers, their growth, your feedback. Short and regular beats long and rare.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Friday</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">The report the founder does not have to ask for</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Numbers, decisions needed, risks, and what changed. One page, same shape every week.</p></div></li></ol></section></div><section id=\"tools\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">The tools, and why each one exists</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Do not buy anything yet. Learn the free ones properly and use the client's licence for the rest — that is what everyone else is doing too.</p><div class=\"mt-8 space-y-8\"><div><p class=\"eyebrow text-muted\">Running the work</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">ClickUp / Asana / Notion</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">One system of record for tasks, owners, and dates. Pick one and enforce it.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Notion or Google Docs</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The SOP library. Searchable, versioned, and linked from the task that uses it.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Loom</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Training and handoffs at scale. One recording replaces the same explanation eleven times.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Slack</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Channels by function, not by person. Decisions posted publicly so they survive the people who made them.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Sheets or Looker Studio</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The weekly scorecard. Boring, reliable, and nobody needs a licence to read it.</p></li></ul></div><div><p class=\"eyebrow text-muted\">Managing people</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">A written role scorecard</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">What good looks like for each seat, in measurable terms. Hiring and reviews both get easier.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Hubstaff or Time Doctor</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">If your team is tracked, you own the policy. Know it before you enforce it.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">OnlineJobs.ph employer account</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Where you will hire your own VAs once the client trusts you to build the team.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">A paid test task template</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Two to three hours, scoped, paid. The only reliable predictor of how someone works.</p></li></ul></div><div><p class=\"eyebrow text-muted\">Automation, used carefully</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Zapier or Make</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Form to task, payment to sheet, review request after job completion. Small and documented.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Airtable</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">When a spreadsheet becomes a database with three people editing it, move before it breaks.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">An automation register</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">A list of every zap, what it does, who owns it, and how to turn it off. Nobody ever has this.</p></li></ul></div></div></div></section>"},{"kind":"slot","value":"MODULES","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"keep-learning\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Keep learning<span class=\"dot\" aria-hidden=\"true\">.</span></h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Hand-picked and free. These open in a new tab — official docs, academies and channels that go deeper on what this track teaches. No affiliate links, no sign-up walls.</p><ul class=\"mt-8 grid gap-3 sm:grid-cols-2\"><li class=\"h-full\"><a href=\"https://academy.asana.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Asana Academy</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Free certificates on project workflows — hiring managers recognise them.</p></a></li><li class=\"h-full\"><a href=\"https://university.clickup.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">ClickUp University</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The other tool half your clients run. Free courses.</p></a></li><li class=\"h-full\"><a href=\"https://www.process.st/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Process Street</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Read their checklist examples to see what professional SOPs look like.</p></a></li><li class=\"h-full\"><a href=\"https://www.notion.com/help\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Notion Help &amp; Academy</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Ops leads build the wiki. Learn relations and rollups properly.</p></a></li></ul></section></div>"},{"kind":"html","value":"<section class=\"border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><section id=\"rates\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What this actually pays</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Two reference points, because ops leadership sits off the end of the VA ladder. The OnlineJobs.ph April 2026 guide tops out around $10 to $12 for expert general VA work, since it measures VA roles. Indeed PH puts the average operations manager base salary at ₱45,089 a month as of June 2026, from about 1,600 reported salaries. Direct engagements with US and AU clients typically sit above both and are usually priced as a monthly retainer rather than hourly. Treat the top band as observed in the market rather than benchmarked, and always price against the leaks you close.</p><div class=\"mt-7 rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><div class=\"space-y-7\"><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Senior VA / coordinator</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">10–13<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:28.57142857142857%;width:8.571428571428571%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Owns a function end to end. Nobody checks your work, but you do not yet own anyone else's.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 1,600–2,080/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Operations manager</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">13–20<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:37.142857142857146%;width:20%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Owns outcomes and one or two people. Runs the rhythm, holds the scorecard, hires the seat below.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 2,080–3,200/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Fractional ops lead / OBM</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">20–35<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:57.14285714285714%;width:42.857142857142854%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Two or three clients, retainer not hourly, paid for judgment. Observed on direct engagements, not from the PH guide.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 3,200–5,600/mo full-time</p></div></div></div><p class=\"mt-7 border-t border-line pt-4 text-[0.75rem] leading-relaxed text-muted-2\">Directional market benchmarks, not a guarantee and not a ceiling. Source: <a href=\"https://ph.indeed.com/career/operations-manager/salaries\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">OnlineJobs.ph salary guide (Apr 2026) and Indeed PH operations manager salaries (Jun 2026)</a>. Monthly figures assume 40 hours a week, which most VA roles are not.</p></div><div class=\"mt-5 rounded-2xl border border-[#f4d9c6] bg-clay-wash/70 p-6 sm:p-7\"><p class=\"eyebrow text-clay-deep\">What actually moves you up a band</p><ul class=\"mt-3.5 grid gap-2.5 sm:grid-cols-2\"><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You own a number, not a task list</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You hired someone and their output is now your responsibility</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You have written decision rights with a threshold attached</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>The weekly report goes out without anyone asking for it</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You built the SOP library the team is trained on</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You can show money recovered or time returned, with the arithmetic</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You moved from hourly to a monthly retainer</li></ul></div></section></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><figure class=\"rounded-2xl border border-line bg-card p-7 shadow-card sm:p-9\"><figcaption class=\"flex flex-wrap items-center gap-3\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">Worker story</span><span class=\"text-[0.8125rem] text-muted\">One person's experience, not a universal rule</span></figcaption><h2 class=\"mt-4 font-display text-[1.5rem] font-semibold leading-snug text-ink\">The VA who stopped being the one doing the work</h2><blockquote class=\"mt-5 border-l-2 border-clay pl-5 font-display text-[1.1875rem] italic leading-relaxed text-ink\">“I present myself to the client as a person with team that helping me work. Currently earning more than 400k a month now, 300k na ppocket ko the rest are for paying my team.”</blockquote><p class=\"mt-5 text-[0.9375rem] leading-relaxed text-ink-2\">In an August 2026 r/buhaydigital thread about VAs earning six figures a month, one reply described a different route out. He holds three clients and outsources delivery to a small team he trains, presenting himself openly as someone who works with a team rather than alone. His first client, a CEO, gave permission to work with others as long as they were not direct competitors, then referred him to a CEO friend a year later, which became client three. He works in a niche with very little competition, keeps expanding and training people because he is aware he could lose work at any time, and says his goal is to manage rather than deliver directly.</p><div class=\"mt-5 rounded-xl border border-teal-pale bg-teal-wash/60 p-4\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The lesson</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The pay ceiling is attached to being the hands. It lifts when you own outcomes, when someone else's output is your responsibility, and when a client is buying a system rather than your availability. Notice also what made it durable: permission agreed up front, no direct competitors, referrals from a happy client, and constant awareness that any single client can disappear.</p></div><a href=\"https://old.reddit.com/r/buhaydigital/comments/1veawtz/tanong_ko_lang_sa_mga_va_dito_earning_6_digits/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"mt-4 inline-block text-[0.8125rem] font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">Read the original thread — r/buhaydigital, August 2026</a></figure></div><section id=\"first-client\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Getting the first one to say yes</h2><ol class=\"mt-7 space-y-4\"><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">01</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Start where you already are</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">The cheapest ops lead role to get is the one inside a client you already serve. They know you, and the mapping exercise costs you a weekend rather than a job search.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">02</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Do the diagnosis unpaid, once</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">One process map and one five-metric baseline, unpaid, capped at eight hours. It is the only pitch that cannot be argued with, because it is about their business rather than your CV.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">03</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Ask for the title before the money</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Titles are free and they compound. Being called operations lead on one engagement is what makes the next one believe you, and the rate follows the title by about six months.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">04</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Apply to the adjacent job titles</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Operations manager, online business manager, delivery manager, chief of staff, integrator, remote operations coordinator. Searching only for \"VA\" keeps you in the pay band you are trying to leave.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">05</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Build the team before you are asked to</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Propose the hire, write the scorecard, run the test task, manage the person. Managing one contractor is the qualification, and nobody is going to hand it to you first.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">06</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Cap client concentration deliberately</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">Two or three clients at retainer, none above half your income. Ops leads who depend on one founder are not leads, they are employees with worse protection.</p></div></li></ol><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">What goes in the portfolio</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">Every one of these comes out of the exercises above. Finish the track and you have the folder, not just the knowledge.</p><ul class=\"mt-5 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A lead-to-cash process map with leaks marked</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Instantly legible to a founder and impossible to fake. The strongest single artefact in this track.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A five-metric weekly scorecard with baselines</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Proves you think in numbers rather than in effort.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Three SOPs with owners, review dates, and failure branches</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Shows you build systems that survive you, which is the definition of the role.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A role scorecard and paid test task with a rubric</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Evidence you can hire, which is the line between senior VA and manager.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A decision log covering three months</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">The artefact almost nobody has, and the one that reads most senior.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">An automation register with manual fallbacks</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Signals that you think about risk, not just cleverness.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">A 90-day operations plan with value arithmetic</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">This is the document you get hired on. Everything else supports it.</p></li></ul></div></section>"},{"kind":"slot","value":"QUIZ","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":""},{"kind":"slot","value":"GLOSSARY","wrappers":[{"tag":"section","class":"border-y border-line bg-paper-2/70 py-14 sm:py-20"},{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"red-flags\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Walk away when you see these</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Not every one of these is a scam. Some are just clients who will cost you more than they pay you, which ends the same way.</p><ul class=\"mt-7 space-y-3\"><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>You are given the responsibility but not the authority</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Accountable for delivery with no ability to decide or assign is the fastest burnout in this job. Get thresholds in writing.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>The title changes and the pay does not</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Operations manager at VA money is a very common and very deliberate trade. Renegotiate at the point of the title, not later.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>\"Just manage the team\" with no scorecard and no hiring input</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">You are being handed blame for people you did not choose and cannot measure.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>The founder overrides your decisions in public</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Twice is a pattern. Your authority with the team is gone and no amount of process fixes it.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Every process improvement gets approved and never resourced</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Enthusiasm without time or budget means the improvement will be done by you at midnight, permanently.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>You are the only person who understands the systems</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">It feels like security. It is a cap. You cannot be promoted out of a role nobody else can run.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Contractors are paid late and you are the one telling them</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">You are absorbing the reputational cost of someone else's cash flow. Fix it upstream or stop being the messenger.</p></li></ul></section></div><section id=\"faq\" class=\"scroll-mt-32 border-t border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Questions people actually ask</h2><div class=\"mt-7 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Do I need to manage people to be an ops lead?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Eventually yes, and it does not have to be many. One contractor whose output you are accountable for is the qualification. Owning a system with nobody in it is senior VA work, which is a fine job and a different pay band.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">My client will not create the role. What now?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Do the diagnosis anyway, capped at eight hours, and keep it. A process map, a scorecard and a 90-day plan for a real business is the portfolio that gets you hired elsewhere as an ops manager. The work is not wasted just because that particular founder said no.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Should I still be hourly as an ops lead?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">No. Once you are paid for outcomes, hourly billing punishes you for every efficiency you create. Move to a monthly retainer with stated hours and scope, and put the review date in the agreement.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">How do I manage someone older or more experienced than me?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">With clarity rather than authority. Agree the outcomes, agree how they are measured, then hold to those in writing. Most friction there is not about age, it is about someone not knowing what they are being judged on.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Is an OBM certification worth it?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Rarely for getting hired, sometimes for confidence and structure. Clients ask for a plan and evidence you have run one. A 90-day plan with real arithmetic in it beats any certificate, and it costs a weekend.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">What if I hire someone and they are bad?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Then you learn the actual skill, which is acting quickly and kindly. Two clear conversations, one written expectation, a date, then a decision. Carrying someone quietly for six months is the mistake, not the bad hire.</p></details></div><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">Where the facts in this course came from</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">All free, all worth your time. Open them in another tab and check us.</p><ul class=\"mt-5 space-y-2.5\"><li><a href=\"https://ph.indeed.com/career/operations-manager/salaries\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Indeed PH: operations manager salaries</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Reported Philippine operations manager pay. The reference point once you leave the VA ladder.</span></a></li><li><a href=\"https://blog.onlinejobs.ph/comprehensive-guide-to-virtual-assistant-salaries-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">OnlineJobs.ph salary guide</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">The VA ceiling you are pricing above. Useful for showing a client where the ladder ends.</span></a></li><li><a href=\"https://www.obmschool.com/how-to-transition-from-va-to-obm/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">OBM School: transitioning from VA to online business manager</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">A course seller's blog, so read past the pitch, but the framing of claiming the role is correct.</span></a></li><li><a href=\"https://thevirtualsavvy.com/online-business-manager/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">The Virtual Savvy: OBM vs VA</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Clear breakdown of what an OBM actually owns compared to a VA. Useful vocabulary for a pitch.</span></a></li><li><a href=\"https://old.reddit.com/r/buhaydigital/comments/1veawtz/tanong_ko_lang_sa_mga_va_dito_earning_6_digits/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">r/buhaydigital: VAs earning six figures a month</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">The thread behind this track's worker story. Read the outsourcing reply and the one about VA as a starting point.</span></a></li></ul></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-16\"><div class=\"rounded-2xl border border-line bg-clay-wash/60 p-7 sm:p-9\"><h2 class=\"font-display text-[1.5rem] font-semibold text-ink\">Finished? Go and use it.</h2><p class=\"mt-3 max-w-lg text-[0.9375rem] leading-relaxed text-ink-2\">The board updates every 30 minutes. Filter for this specialism, check your number against the rate tool, and send five tailored applications rather than fifty copy-pasted ones.</p><div class=\"mt-6 flex flex-wrap gap-3\"><a class=\"btn btn-primary\" href=\"/jobs\">See jobs on the board</a><a class=\"btn btn-ghost\" href=\"/pricing-tool\">Check your rate</a></div></div><div class=\"mt-10\"><p class=\"eyebrow text-muted\">Other written tracks</p><ul class=\"mt-3 flex flex-wrap gap-2.5\"><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/executive-assistant\">Executive Assistant</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/seo-specialist\">SEO Specialist VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/social-media-manager\">Social Media Manager VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/real-estate-va\">Real Estate VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/ecommerce-va\">E-commerce VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/complete-va-starter\">The Complete VA Starter</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/applications-that-get-replies\">Applications That Get Replies</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/pricing-and-negotiation\">Pricing &amp; Negotiation</a></li></ul></div><a class=\"btn btn-ghost mt-8\" href=\"/courses\">← All courses</a></div><!--$--><!--/$-->"}],"modules":[{"n":1,"title":"The shift from tasks to outcomes","outcome":"You can describe your job as a set of outcomes you are accountable for, and you know which behaviours you have to give up.","badges":["Time split","Rates","Red/green flags"],"minutes":24,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A VA is measured on whether they did what was asked. An ops lead is measured on whether the thing worked, including when nobody asked.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The first behaviour to drop is waiting. If you find yourself thinking \"I told them and they did not reply\", that is now your unresolved problem, not theirs.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The second is heroics. Fixing a broken process yourself at 11pm feels like ownership and is actually the thing preventing the fix.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Claim the role deliberately. The transition guidance from people who train OBMs is consistent: many VAs are already doing operations work and stay underpaid because they never renamed what they do or asked to be paid for it.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Outcomes must be countable or dated. \"Improve client onboarding\" is not an outcome. \"Every new client is live within five business days\" is.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You will feel less productive for about a month. Your output moves from things you made to things other people shipped, and that shows up later.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The same job, rewritten as outcomes</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Manage the project board</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Follow up with contractors</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Send the weekly report</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Onboard new clients</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Help with anything else needed</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Every active project has an owner and a next action, checked daily. Target: zero stale cards over 3 days.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Contractor deliverables land by the agreed date. Target: 90 percent on time, measured monthly.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">The founder gets a decision-ready report every Friday by 9am, without asking.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">New clients are fully live within 5 business days of signing. Target: median 4 days.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Anything outside these four is a change request with a time estimate, not \"anything else needed\".</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The second list can be graded by someone who was not in the room. That is the whole difference, and it is also why it pays more.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Where the hours go</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">How an ops lead's week differs from a senior VA's</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The same 40 hours, redistributed. Notice the largest slice is now other people's work rather than your own.</p><div class=\"mt-4\"><div class=\"flex flex-col items-center gap-5 sm:flex-row sm:items-start sm:gap-7\"><svg viewBox=\"0 0 140 140\" class=\"h-[8.5rem] w-[8.5rem] shrink-0 -rotate-90\" role=\"img\" aria-labelledby=\"_R_b1lanpfiuqbtb_\"><title id=\"_R_b1lanpfiuqbtb_\">Managing people: 1:1s, reviews, unblocking 26%, Systems: building and fixing processes 22%, Measuring and reporting 16%, Managing upward and stakeholders 14%, Doing the work yourself 12%, Hiring and onboarding 10%</title><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"var(--color-line)\" stroke-width=\"20\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#097769\" stroke-width=\"20\" stroke-dasharray=\"91.48317807253478 260.37519912952206\" stroke-dashoffset=\"0\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#5fd0bf\" stroke-width=\"20\" stroke-dasharray=\"77.4088429844525 274.4495342176043\" stroke-dashoffset=\"-91.48317807253478\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#075f55\" stroke-width=\"20\" stroke-dasharray=\"56.297340352329094 295.5610368497277\" stroke-dashoffset=\"-168.8920210569873\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#4453b8\" stroke-width=\"20\" stroke-dasharray=\"49.26017280828796 302.59820439376887\" stroke-dashoffset=\"-225.18936140931638\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#e07a2f\" stroke-width=\"20\" stroke-dasharray=\"42.223005264246815 309.63537193781\" stroke-dashoffset=\"-274.4495342176043\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#c3e6df\" stroke-width=\"20\" stroke-dasharray=\"35.18583772020568 316.6725394818511\" stroke-dashoffset=\"-316.6725394818511\"></circle></svg><ul class=\"w-full space-y-2\"><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#097769\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Managing people: 1:1s, reviews, unblocking</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">26%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">The job you didn't apply for and now can't avoid. Get good at it.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#5fd0bf\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Systems: building and fixing processes</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">22%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">The actual product. Every hour here saves someone ten later.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#075f55\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Measuring and reporting</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">16%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">You can't run what you can't see, and the founder decides based on what you show them.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#4453b8\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Managing upward and stakeholders</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">14%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Underrated. Most ops people fail here, not on the operations.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#e07a2f\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Doing the work yourself</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">12%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Should keep shrinking. If it's growing, you're a senior VA with a title.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#c3e6df\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Hiring and onboarding</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">10%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Bursty, and the highest-consequence thing on this list.</p></li></ul></div><p class=\"mt-4 border-t border-line pt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Only 12% is you doing tasks. The hardest part of this transition is emotional — task completion feels productive, and you have to give up that feeling to do the job you're now paid for.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">What ops leadership pays</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">This is the top of the ladder that starts at $3/hr data entry. The jump from senior VA to ops lead is the largest single pay step in this career, and it's about scope of responsibility, not hours.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:38rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Senior VA (owns their own work)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$11–16</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,800–2,600</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Reliable, unsupervised, deep in one lane. The launchpad.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Ops coordinator</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$13–18</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$2,100–2,900</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You own a process end to end and other people follow it.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Ops manager</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$16–24</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$2,600–3,900</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You manage 2–5 people and own a set of numbers. First real management role.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Ops lead / head of ops</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$20–32</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$3,200–5,200</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You own the operating rhythm of the whole company. You're in the strategy conversations.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Fractional ops (2–3 clients)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$30–60</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,500–3,000 per client</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The highest-earning shape. Sell 10 hrs/week to three companies, not 40 to one.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><div class=\"mt-4\"><p class=\"eyebrow mb-2 text-muted\">Same skill, different client</p><ul class=\"grid gap-2 sm:grid-cols-2\"><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Verse's job board (ops/PM median)</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$5.40</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">But the top of that range reaches $29/hr. Ops posts have the widest spread on the whole board.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Promoted internally</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">+30–60%</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">The most common path, and usually the easiest. Become indispensable, then ask.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Hired directly as ops</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$18–30</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Needs a portfolio of systems you've built. This course is that portfolio.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Fractional / consulting</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$30–60</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Highest ceiling, most instability. Do it after you've done it in-house once.</p></li></ul></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Sources: Verse's live board (ops/PM listings show the widest range of any category), plus 2026 offshore ops rate benchmarks. The spread is enormous because 'ops' means both 'admin with a nicer title' and 'runs the company'.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">You've been promoted to ops lead and something urgent breaks</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Rolling up your sleeves and fixing it yourself at 11pm, because you're fastest and it needs doing. Then doing the same next week, and the week after.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">This feels like leadership and is the opposite. You've taught the team that escalation means you'll absorb it, guaranteed yourself a second full-time job, and learned nothing about why it broke.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Fix it with the person whose job it is, on a call, while they drive. Then the next day: \"Why did this reach us at 11pm? What would have caught it at 4pm?\" Change the process, not just the outcome.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">The failure gets fixed AND the class of failure gets fixed. Your value isn't that you can do everyone's job faster — it's that problems stop recurring.</p></div></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Rewrite your current job description, real or imagined, as four to six outcomes with a target attached to each.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page outcomes list you would be comfortable being reviewed against.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 40 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">Every outcome has a number or a date</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">None of them begin with the words manage, help, or assist</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">You deleted or converted the catch-all line</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">You could be graded on this list by a stranger</span></label></li></ul></div>"},{"n":2,"title":"Map the business before you change it","outcome":"You can produce a process inventory that shows where work enters, where it stalls, and where money leaks.","badges":["Workflow","1 template"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You cannot improve what you cannot see. Before touching anything, list every recurring process, who runs it, how often, and what it produces.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Follow the money and the customer. Map lead to cash: enquiry, quote, sale, delivery, invoice, payment, review. Most of the damage is in the handoffs between those steps.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Every handoff is a place work can die. Count them, then ask what happens if the person on the receiving end is on leave.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Look for the four classic leaks: work waiting on one person, work done twice, work with no owner, and work nobody checks.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Ask each person the same two questions: what takes longer than it should, and what do you redo most often. You will get the real map in an afternoon.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Rank by cost, not by annoyance. The loudest complaint is rarely the most expensive problem.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Wilder and Co: lead to cash, with the leaks marked</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">1. Enquiry lands in a shared inbox. Nobody owns the inbox. LEAK: median first reply 19 hours.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">2. Account manager writes a quote from scratch each time. LEAK: the same six services re-priced by hand, inconsistently.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">3. Client signs by email reply. No countersignature, no start date recorded. LEAK: onboarding starts whenever someone notices.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">4. Work assigned in Slack DMs. LEAK: no board, so nothing is visible when someone is sick.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">5. Delivery reviewed by the founder personally. LEAK: single point of failure, average 3-day wait for approval.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">6. Invoice raised manually at month end from memory. LEAK: two projects last quarter were never invoiced at all.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">7. No review request is ever sent. LEAK: 4 reviews in 18 months for a company that finishes 15 jobs a month.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Ranked by cost: step 6 first, it is literal lost revenue. Then step 1, then step 5.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Seven steps, seven leaks, and the most expensive one had never been mentioned by anybody because nobody could see the whole line.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Mapping a business in your first 30 days</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">New ops role, or a promotion into one. Resist the urge to change anything yet.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Change nothing for two weeks. Just watch.</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Every obviously stupid process has a reason. Change it before you know the reason and you'll break something invisible and lose credibility in week three.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Follow the money end to end</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">How does a stranger become a customer, and how does the cash arrive? Walk the whole path. Everything else is downstream of this.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Ask everyone the same four questions</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">What takes longest? What do you redo most? What do you wait on? What breaks when you're off? The overlaps between people's answers are your real backlog.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Find the single points of failure</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Which processes live only in one person's head? Which tool has one admin? Which client only talks to one person? Write the list. It's usually alarming.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Draw the actual process, not the official one</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">There's always a gap between the documented flow and what people really do. The gap IS the finding — people route around processes for reasons.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Present findings before proposals</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">\"Here's what I see\" earns trust. \"Here's what you're doing wrong\" earns resistance. Get agreement on the diagnosis before you offer a cure.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Arriving with a plan from your last job. Every business is weird in its own specific way, and the fastest route to being ignored is proposing solutions to problems this company doesn't have.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Process discovery interview</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Run with every person in the business, 30 minutes each. Same questions, so you can compare answers.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>PERSON: [name, role] | Date: [date]\n\nTHEIR WORK\n1. Walk me through a normal day. Start to finish.\n2. What's the thing you do most often?\n3. What takes the longest, and what makes it take that long?\n\nWHERE IT HURTS\n4. What do you find yourself redoing?\n5. What are you usually waiting on, and who from?\n6. What breaks when you're on leave?\n7. What's the thing that would make you actually happy if it went away?\n8. What do people ask you that they could find out themselves?\n\nTHE HIDDEN STUFF\n9. Is there anything you do differently from how it's officially supposed to be done?\n   [Ask gently. Promise you're not policing. This answer is usually the single most valuable thing in the interview.]\n10. What's the workaround everyone knows about?\n11. What did someone try to change before that didn't work? Why not?\n\nTOOLS\n12. What do you use daily? What do you hate about it?\n13. Anything you're paying for and not using?\n14. What are you doing in a spreadsheet that probably shouldn't be?\n\nCLOSING\n15. If you could change one thing, what?\n16. Who else should I talk to?\n\nAFTER EVERY INTERVIEW, NOTE:\n• Their #1 pain in their own words: \"[quote]\"\n• Single point of failure risk: [what only they know]\n• Quick win I spotted: [something fixable in under a day]\n\nAFTER ALL INTERVIEWS — look for these patterns\n• The same pain named by 3+ people → that's your first project\n• A process nobody describes the same way → it isn't documented, it's folklore\n• A tool everyone complains about → check the contract renewal date\n• A person named as a blocker by several people → usually overloaded, not obstructive</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Map lead to cash for a business you know, real or the Wilder and Co scenario. Mark every handoff and every leak, then rank by cost.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page process map plus a ranked leak list with an estimated cost for the top three.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 60 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">Every step names an owner, even if the answer is nobody</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">Handoffs are explicitly marked</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">The ranking is by cost, with your estimate shown</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">You noted at least one process that exists only in one person's head</span></label></li></ul></div>"},{"n":3,"title":"The SOP library","outcome":"You can build documentation that people actually use, and you know why most SOP projects die.","badges":["Workflow","Tools","1 template"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">SOP projects fail for three reasons: they were written all at once, they live somewhere nobody opens, and nobody owns keeping them true.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Write them in the flow of work. The person doing the task writes the draft the second time they do it, and you edit. Never assign someone a week of writing documentation.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Link the SOP from the task, not from a folder. If reaching the document takes more than one click from where the work happens, it will not be read.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Every SOP needs an owner and a review date. An SOP nobody owns becomes wrong within three months and then actively harmful.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Pair the doc with a Loom. Reading suits some people, watching suits others, and the recording takes four minutes to make.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Test by handing it to someone who has never done the task. If they can complete it without messaging you, it is finished. If they ask one question, that question is the missing step.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The SOP header that keeps a library alive</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Title: Monthly invoicing run, Wilder and Co</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Owner: Ops lead. Reviewed: 1 Aug 2026. Next review: 1 Nov 2026.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Purpose: every completed project is invoiced within 3 business days of month end. No project ever goes unbilled.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Trigger: last working day of the month, 9am.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Prerequisites: access to the delivery board, QuickBooks, and the signed scope folder.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Steps: numbered, one verb each, with screenshots.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Failure branch: if a project has no signed scope on file, do not invoice. Flag it to the account manager and log it in the Exceptions tab that day.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Done when: every card in Delivered has an invoice number recorded, and the Exceptions tab is empty or explained.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Loom: 4 minutes, linked at the top.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The owner line and the review date are what separate a living library from a graveyard of documents written in one enthusiastic weekend.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Building an SOP library people actually use</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Once you've mapped the business. Prioritise ruthlessly — you cannot document everything.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Rank by (frequency × pain × bus-factor)</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Document the daily thing only one person knows first. Not the annual thing everyone can do.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Have the person who does it write the first draft</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">You edit. This is faster, more accurate, and it means they own it rather than resenting your version of their job.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Test it on someone who's never done the task</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The real test. If they can complete it without asking a question, it works. If they ask three questions, those three answers are what's missing.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Store everything in ONE place with a naming convention</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Six SOPs in one findable folder beat sixty scattered across Drive, Notion and someone's desktop.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Put a review date and an owner on every single one</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">An SOP with no owner rots. A rotten SOP is worse than none because people follow it into a wall.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Make following them the default, visibly</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Link the SOP in the task. Reference it in the 1:1. If you don't use them yourself, nobody else will either.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Spending six weeks building a beautiful library that nobody opens. Documentation that isn't linked from where the work happens is a filing cabinet in a locked room.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Tool comparison</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Where to put the documentation</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The tool matters far less than the discipline. But pick badly and you add friction to something already unpopular.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:52rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Tool</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Best for</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Learning curve</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Cost</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Verdict</th></tr></thead><tbody><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Notion</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Most small teams. Databases, templates, and a search that works.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — a weekend</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier, $10/user/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Best default for a company under 50 people. Build one SOP database with owner, review date and status as properties, and you have a management system, not a folder.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Google Docs + Drive</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Teams already deep in Workspace who won't adopt anything new.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">None</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Underrated. A well-named Drive folder with a single index doc beats an abandoned Notion. Adoption beats features.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Loom</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Anything faster to show than to write.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Instant</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Pair every fiddly SOP with a 2-minute video. Video plus a five-bullet checklist is the highest-adoption format there is.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Scribe / Tango</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Auto-generating click-by-click guides with screenshots.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Instant</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Genuinely magic for software walkthroughs — records your clicks and writes the steps. Cuts SOP writing time by more than half.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Slite / Confluence</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Larger orgs with compliance requirements.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">$8–15/user/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Only if you're required to. Heavier than a small team needs and adoption suffers accordingly.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">ClickUp / Asana docs</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Keeping the SOP inside the task tool.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy if you already use it</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Bundled</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Real advantage: the SOP sits where the work happens. Real risk: it's mediocre as a document tool. Fine for short procedures.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 5 columns and scrolls horizontally on small screens.</span></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">SOP library index</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">One table, the front door to everything. Without an index, a library is a pile.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><div class=\"p-3.5 space-y-3\"><div class=\"overflow-x-auto rounded-lg border border-line\"><table class=\"w-full min-w-[600px] text-[0.8125rem]\"><thead><tr class=\"bg-paper-2\"><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">#</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Process</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Owner</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Frequency</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Bus factor</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Last reviewed</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Review due</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Status</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Link</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">01</td><td class=\"px-3 py-2.5 text-ink-2\">Client onboarding</td><td class=\"px-3 py-2.5 text-ink-2\">Maria</td><td class=\"px-3 py-2.5 text-ink-2\">Per new client</td><td class=\"px-3 py-2.5 text-ink-2\">1 ⚠</td><td class=\"px-3 py-2.5 text-ink-2\">Mar 2026</td><td class=\"px-3 py-2.5 text-ink-2\">Sep 2026</td><td class=\"px-3 py-2.5 text-ink-2\">Live</td><td class=\"px-3 py-2.5 text-ink-2\">[link]</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">02</td><td class=\"px-3 py-2.5 text-ink-2\">Weekly invoicing</td><td class=\"px-3 py-2.5 text-ink-2\">Ben</td><td class=\"px-3 py-2.5 text-ink-2\">Weekly</td><td class=\"px-3 py-2.5 text-ink-2\">2</td><td class=\"px-3 py-2.5 text-ink-2\">Feb 2026</td><td class=\"px-3 py-2.5 text-ink-2\">Aug 2026</td><td class=\"px-3 py-2.5 text-ink-2\">Live</td><td class=\"px-3 py-2.5 text-ink-2\">[link]</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">03</td><td class=\"px-3 py-2.5 text-ink-2\">Monthly reporting</td><td class=\"px-3 py-2.5 text-ink-2\">Me</td><td class=\"px-3 py-2.5 text-ink-2\">Monthly</td><td class=\"px-3 py-2.5 text-ink-2\">1 ⚠</td><td class=\"px-3 py-2.5 text-ink-2\">Mar 2026</td><td class=\"px-3 py-2.5 text-ink-2\">Jun 2026</td><td class=\"px-3 py-2.5 text-ink-2\">Draft</td><td class=\"px-3 py-2.5 text-ink-2\">[link]</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">04</td><td class=\"px-3 py-2.5 text-ink-2\">New VA onboarding</td><td class=\"px-3 py-2.5 text-ink-2\">Me</td><td class=\"px-3 py-2.5 text-ink-2\">Ad hoc</td><td class=\"px-3 py-2.5 text-ink-2\">1 ⚠</td><td class=\"px-3 py-2.5 text-ink-2\">—</td><td class=\"px-3 py-2.5 text-ink-2\">—</td><td class=\"px-3 py-2.5 text-ink-2\">Not written</td><td class=\"px-3 py-2.5 text-ink-2\">—</td></tr></tbody></table></div><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">BUS FACTOR = how many people could do this if someone vanished tomorrow.\nAnything at 1 is a live risk to the business. Fix those first, in frequency order.\n\nPRIORITISATION SCORE = frequency × pain × (4 − bus factor)\nScore everything, sort descending, work down the list. It stops you documenting\nthe interesting thing instead of the important thing.\n\nRULES\n• Every SOP has ONE named owner. Not a team. A person.\n• Review date on every one — 6 months default, 3 for anything volatile\n• Status: Not written → Draft → Tested → Live → Needs update\n• \"Tested\" means someone who'd never done it followed it successfully\n• Anything not reviewed in 12 months gets archived, not left to mislead people</pre></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write two SOPs for your mapped process, using the header format. Then have someone unfamiliar run one and note every question they ask.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: Two SOPs, one tested, plus a list of the gaps the tester found.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 75 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">Both have an owner and a review date</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">Both have a failure branch</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">The tester completed the task without messaging you, or you fixed the step that made them</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"><span class=\"\">Each is linked from the actual task or board it belongs to</span></label></li></ul></div>"},{"n":4,"title":"Measuring the right five things","outcome":"You can build a weekly scorecard that survives contact with a busy founder and drives at least one decision.","badges":["Red/green flags","1 template"],"minutes":28,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Five numbers, maximum. A dashboard with thirty metrics is a way of measuring nothing while looking diligent.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Pick one number per stage of the money line: speed in, throughput, quality, cost, and cash. If you cannot connect a metric to one of those, cut it.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Every metric needs a baseline and a target. A number with no comparison is trivia.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Prefer medians to averages for anything involving time. One catastrophic outlier drags an average and hides the normal week.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Count things you can actually collect weekly by hand at first. An imperfect number gathered every Friday beats a perfect dashboard that never ships.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Attach an owner to each metric. Numbers without a name attached drift for months while everyone assumes someone else is watching.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Wilder and Co scorecard, week 34</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Speed to first reply, median: 2.1 hrs (baseline 19 hrs, target under 2). Owner: support VA. Green.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Projects delivered on time: 11 of 14, 79 percent (target 90). Owner: ops lead. Amber, two were waiting on founder approval.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Rework rate: 3 of 14 needed a redo, 21 percent (baseline 30, target under 10). Owner: delivery VA. Amber.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Unbilled completed projects: 0 (baseline 2 last quarter, target 0). Owner: ops lead. Green.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Reviews requested vs received: 14 sent, 5 received (baseline 0). Owner: support VA. Green, new process.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Decision needed from you: approvals are the bottleneck on 2 of the 3 late projects. I propose I approve anything under $2,000 and escalate the rest. Yes or no by Wednesday.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Five numbers and one decision. The decision line is what makes a founder read it, and it is the thing that converts a report into authority.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">The dashboard you build for the founder</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">A 40-metric dashboard tracking everything the tools can export, updated in real time, that nobody opens after week two.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Forty numbers is zero numbers, because there's no signal about what to do. Real-time updates on metrics nobody acts on daily are decoration. Building it feels productive and changes nothing.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Five numbers on one screen. Each one has a target, a trend arrow, and a named owner. Anything off-target is red and has a one-line note saying what's being done about it.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Five numbers with owners and targets is a management system. Forty numbers is a report. The test is simple: can someone look at this and know whether to be worried, and who to talk to?</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A metric goes the wrong way</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Waiting until the monthly report, then presenting it with a chart and no explanation. Or quietly changing how it's calculated so it looks better.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">The first means the founder finds out too late to act, and learns that your reports lag reality. The second is the beginning of the end — once numbers can't be trusted, you can't be either.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"Heads up before the monthly: onboarding time went from 3 days to 6 in the last fortnight. Cause is that Maria's covering two roles while Ben's on leave. It'll self-correct on the 14th, but if it doesn't I'll need a temp. Flagging now so it's not a surprise.\"</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Early, with a cause, a prediction and a contingency. Founders can handle bad numbers. What they can't handle is discovering bad numbers late from someone whose job was to watch them.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The five-metric scorecard</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Pick exactly five. The discipline of choosing is the valuable part — it forces you to decide what the business is actually for.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><div class=\"p-3.5 space-y-3\"><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">[COMPANY] SCORECARD — week of [date]</pre><div class=\"overflow-x-auto rounded-lg border border-line\"><table class=\"w-full min-w-[600px] text-[0.8125rem]\"><thead><tr class=\"bg-paper-2\"><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">#</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Metric</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Target</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">This wk</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Last wk</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Trend</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Owner</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Status</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">1</td><td class=\"px-3 py-2.5 text-ink-2\">[Revenue metric]</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\">↑</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\">🟢</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">2</td><td class=\"px-3 py-2.5 text-ink-2\">[Delivery/quality metric]</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\">→</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\">🟢</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">3</td><td class=\"px-3 py-2.5 text-ink-2\">[Speed metric]</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\">↓</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\">🔴</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">4</td><td class=\"px-3 py-2.5 text-ink-2\">[Customer metric]</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\">↑</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\">🟢</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">5</td><td class=\"px-3 py-2.5 text-ink-2\">[Team/capacity metric]</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\">→</td><td class=\"px-3 py-2.5 text-ink-2\"><span class=\"text-muted-2\">—</span></td><td class=\"px-3 py-2.5 text-ink-2\">🟡</td></tr></tbody></table></div><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">🔴 ANYTHING RED NEEDS THREE LINES\nMetric: [name]\nWhy: [the actual cause, not \"it was a busy week\"]\nDoing: [specific action, owner, date]\n\nHOW TO CHOOSE YOUR FIVE\n1. One money metric — revenue, margin, or cash\n2. One delivery metric — are we doing the thing well?\n3. One speed metric — how long does the core process take?\n4. One customer metric — churn, satisfaction, complaints\n5. One team metric — capacity, utilisation, or something about people\n\nTHE TESTS EVERY METRIC MUST PASS\n• Someone owns it by name\n• There's a target, not just a number\n• Somebody could DO something differently based on it\n• It can't be gamed without the gaming being obvious\n• It's measurable weekly without a person spending an hour compiling it\n\nWHAT NOT TO TRACK\n• Anything you can't act on\n• Anything that takes over 15 minutes a week to gather\n• Vanity metrics — followers, page views, total signups ever\n• Anything measuring effort instead of outcome (hours worked, emails sent, tasks closed)</pre></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build a five-metric scorecard for your mapped business with baselines, targets, owners, and one decision request.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page scorecard in Sheets, populated with real or realistic numbers.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 50 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Exactly five metrics, no more</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Each has a baseline, a target, and a named owner</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Time metrics use medians</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">There is one explicit decision request with a deadline</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You could collect every number in under 30 minutes</span></label></li></ul></div>"},{"n":5,"title":"Hiring your first VA","outcome":"You can write a role, run a paid test task, and choose someone on evidence rather than on interview charm.","badges":["Workflow","2 templates"],"minutes":32,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Write the scorecard before the job post: the three outcomes this seat owns and how each is measured. Recruit against that, not against a wish list of tools.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Post narrowly. \"Support VA for a US home-services agency: inbox first response, review requests, and CRM hygiene, 20 hrs/week, 6am to 10am Eastern\" attracts people who can picture the job.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Screen in this order: does the application address the actual post, then a short async video, then a paid test task, then a call. Charm is the last signal you should weight, not the first.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The paid test task is the whole method. Two to three hours, paid at the offered rate, scoped in writing, and it must resemble the real work. You are grading not only the output but whether they asked good questions and hit the deadline.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Hire for follow-through and written clarity. Tools are learnable in a week and neither of those is.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Pay the test even if you do not hire them. It costs $20 and it is the difference between being a good employer and being one of the ones people warn each other about.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The paid test task brief</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Task: here are 12 sample enquiry emails from a fictional home-services client. Reply to each using the attached tone guide and pricing sheet.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Also flag anything you would not answer without asking, and say what you would ask.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Time: 2 hours maximum, paid at $7/hr regardless of outcome. Do not exceed it; stopping at the limit is part of what I am assessing.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Deadline: 5pm Thursday your time. Send as one Google Doc link.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">What I am grading: did you follow the tone guide, did you catch the two enquiries that are out of the service area, did you flag the one with a pricing conflict rather than guessing, and did you hit the deadline.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Two of the twelve emails contain traps. Nobody is told which.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The trap emails are the real test. Anyone can write a nice reply. You are hiring for the instinct to stop and ask when something is wrong.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Hiring your first VA</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">You're the bottleneck and the work is genuinely repeatable. Not before.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Document the role BEFORE you post it</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">If you can't write down what they'll do daily, you're not ready to hire — you're hoping someone will figure out your job for you.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Write a post that repels the wrong people</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">State hours, timezone, rate and the boring parts honestly. A post that attracts 200 applicants is badly written; you want 20 good ones.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Screen with a task, not a CV</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A short PAID task tells you more in an hour than a CV and two interviews. CVs measure who can write a CV.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Interview for judgment, not experience</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Give them a realistic messy scenario and ask what they'd do. Experience tells you where they've been; judgment tells you how they'll handle the thing you haven't thought of.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Check references properly, and ask one specific question</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">\"Would you hire them again?\" Any hesitation before the answer is the answer.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Onboard for 30 days, structured</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Week 1 watch, week 2 shadow, week 3 do-with-review, week 4 own it. Most bad hires are actually bad onboardings.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Hiring someone to do a job you've never documented, then being frustrated they do it differently from how you imagined. They cannot read your mind. The documentation is the job description.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Job post that filters properly</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Honesty is the filter. Every unpleasant truth you include saves you three bad hires.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[ROLE TITLE] — [n] hrs/week, [timezone] overlap required\n\nWHAT THIS IS\n[2 sentences on the company and why this role exists. Real, not marketing.]\n\nWHAT YOU'D DO DAILY\n• [Specific task] — roughly [n] hrs/day\n• [Specific task]\n• [Specific task]\n\nWHAT YOU'D DO WEEKLY\n• [Specific]\n• [Specific]\n\nTHE BORING PARTS — being upfront so nobody's surprised\n• [The genuinely tedious bit. Say it.]\n• [The frustrating bit.]\n[This paragraph halves your applications and doubles your hire quality.]\n\nYOU'LL DO WELL HERE IF\n• You'd rather ask a question than guess\n• You tell me about a mistake before I find it\n• You like a checklist\n\nTHIS ISN'T FOR YOU IF\n• You want variety every day — this role is repetitive on purpose\n• You need someone checking in hourly\n• You can't commit to [the timezone]\n\nREQUIRED\n• [Tool] experience — we won't train from scratch on this one\n• [n] Mbps internet with a backup connection\n• Available [specific hours] [timezone], Mon–Fri\n\nNICE TO HAVE\n• [Tool]\n• [Industry] background\n\nPAY\n$[n]/hour, [n] hrs/week = about $[n]/month.\nReview at 90 days. We raise rates for people who are good; we don't haggle at the start.\n\nHOW TO APPLY\n1. Send [specific thing — not a generic CV]\n2. Tell me about a time [specific scenario relevant to the role]\n3. Start your message with the word [WORD] so I know you read this\n\nPaid trial task ($[n]) before any offer. We don't do unpaid tests.\n\n[The screening word alone eliminates the mass-appliers. Use it every time.]</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Interview scorecard</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Same questions, same scoring, every candidate. Without this you'll hire whoever you liked most, which correlates poorly with who's good.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>CANDIDATE: [name] | ROLE: [role] | Date: [date]\n\nSCENARIO QUESTIONS — score 1–5 each\n1. \"You're halfway through a task and realise you misunderstood the brief.\n    It's due in two hours. What do you do?\"\n   Looking for: tells someone immediately, doesn't hide it, proposes an option.\n   Score: ___ | Notes:\n\n2. \"A client messages at 11pm. You're offline. What's the right response?\"\n   Looking for: knows their hours, doesn't reflexively say \"reply immediately\",\n   distinguishes urgent from loud.\n   Score: ___ | Notes:\n\n3. \"You've been doing a task the same way for 3 months. You realise there's a\n    faster way but it means changing something someone else set up. What now?\"\n   Looking for: raises it, doesn't just change it unilaterally, doesn't stay silent.\n   Score: ___ | Notes:\n\n4. \"Tell me about a real mistake you made at work.\"\n   Looking for: an actual mistake, actual impact, a specific behaviour change.\n   Red flag: \"I can't think of one\" or a humble-brag.\n   Score: ___ | Notes:\n\n5. \"What do you need from a manager to do your best work?\"\n   Looking for: self-awareness. Any concrete answer is good.\n   Score: ___ | Notes:\n\nPRACTICALS\nTimezone commitment realistic?          [ ]\nInternet + backup verified?             [ ]\nAudio and setup professional on call?   [ ]\nRate expectation matches budget?        [ ]\nAsked me any questions?                 [ ]  ← no questions is a real flag\n\nPAID TRIAL TASK\nTask set: [what] | Time given: [n] | Time taken: [n]\nQuality: ___/5\nFollowed instructions exactly: ___/5\nAsked clarifying questions before starting: [Y/N]  ← this one predicts most\nCommunication during: ___/5\n\nTOTAL: ___/50\n\nDECISION\n[ ] Offer  [ ] Second trial  [ ] No\n\nOne-line reason: [write it, even for a no — it keeps you honest]\n\n⚠ Before offering, answer this: am I hiring them because they scored well,\nor because I liked them? Being likeable is not the job.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write a role scorecard, a job post, and a paid test task with a written grading rubric for one seat on your team.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: Three documents: scorecard, post, and test brief with rubric.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 60 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The scorecard has three measurable outcomes</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The post states hours in the candidate's time zone as well as the client's</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The test task is capped at three hours and paid</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The rubric says what you are grading, written before you see any submissions</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">At least one deliberate trap is built in</span></label></li></ul></div>"},{"n":6,"title":"Managing people you cannot see","outcome":"You can run one-to-ones, give feedback that changes behaviour, and handle underperformance without either avoiding it or blowing it up.","badges":["Red/green flags","2 templates"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Twenty minutes, twice a week, beats an hour once a month. Same slot, their agenda first, your feedback second, blockers always.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Feedback needs three parts: the specific observation, the effect it had, and what you want instead. Skipping the effect is why most feedback gets nodded at and ignored.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Give it within 48 hours. Feedback saved up for a review is an ambush, and it teaches people that your silence means approval.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Distinguish will from skill before you react. A capable person missing deadlines has a priorities or blockers problem. Someone who does not know how has a training problem. The remedies are opposite.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Write down what good looks like when you correct someone, in one line they can re-read. Verbal corrections evaporate across time zones and languages.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">If performance does not change after two clear conversations and a written expectation, act. Carrying someone quietly is unfair to them, to the team, and to the client paying for it.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Vague feedback and the version that works</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Hey, just try to be a bit more careful with the replies, some of them have been a little off lately. Thanks!\"</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Two things from this week. The Kaplan reply quoted $850 when the sheet says $920, and the Reyes one went out without the booking link.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Effect: Kaplan is now expecting a price we cannot honour, so someone has to walk that back, and Reyes had to email again to book, which is exactly the friction we are trying to remove.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"What I want: before sending, check the price against the sheet and confirm the link is in there. I have added both as the last two lines of the SOP.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Nothing else about the week concerns me. Your response time is the best it has been. What would make the check easier to remember?\"</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Specific, consequence, instruction, then a question that treats them as a person who wants to get it right. It takes ninety seconds and it actually changes behaviour.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Someone on your team is underperforming</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Adding more check-ins, asking for daily screenshots, and monitoring their activity score. Or saying nothing for two months and then putting them on a formal warning.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Surveillance treats a diagnosis problem as a compliance problem, and it destroys the relationship whether or not it works. And silence-then-warning is genuinely unfair — nobody should be shocked by a performance conversation.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"I've noticed [specific, observable thing] over the last few weeks. That's different from how you started. What's going on?\" Then actually listen. It's usually unclear expectations, a missing tool, a personal situation, or a task they never understood and were too embarrassed to ask about.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Names the specific behaviour, not the person. Asks before concluding. Most underperformance is a system problem wearing a person's face, and you'll never find that out by adding monitoring.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Giving feedback to a remote team member</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Saving it all for a quarterly review. Or sending it in a Slack message at the end of the day: \"btw the report had a few issues, can you be more careful next time\"</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Quarterly feedback is archaeology. And async criticism with no chance to respond lands three times harder than you intend — they'll reread it all evening and you won't know.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Within 48 hours, on a call, specific: \"The Peterson report had the wrong quarter's figures. What happened in the process?\" And separately, in writing, the same frequency of specific praise.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Fast, verbal for anything critical, specific about the work rather than the person, and curious about the process. Written criticism to someone you can't see is almost always heavier than you mean it.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The weekly 1:1</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">30 minutes, same time weekly, never cancelled. This meeting is the single highest-leverage thing you do as a manager.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>1:1 — [name] — [date]\n\nTHEIR AGENDA FIRST (10 min)\n[They talk. You don't start with your list. Ask and then be quiet.]\n\"What's on your mind this week?\"\n\nBLOCKERS (5 min)\n\"What are you stuck on or waiting for?\"\n[Your main job in this meeting is removing these. Write down what you'll unblock and by when.]\n• [Blocker] → I'll [action] by [date]\n\nWORK REVIEW (10 min)\nLast week's commitments: [done / not done — no drama either way]\nThis week: [what they're taking on]\nAnything at risk: [what and why]\n\nFEEDBACK (5 min) — both directions, every week\nFrom me: [one specific thing that went well. One specific thing to change.]\nFrom you: \"What could I be doing better for you?\"\n[Ask this every single week. Around week six they'll start actually answering.]\n\nGROWTH — monthly, not weekly\n\"What do you want to be doing in a year?\"\n\"What's one thing you'd like to learn here?\"\n\nRULES\n• Never cancel. Reschedule if you must, never skip. Cancelling says they don't matter.\n• Video on. Text loses everything that makes this useful.\n• No status reports — that's what the tracker is for. This is for the things not in the tracker.\n• Notes in a shared doc so there's a record both of you can see.\n• If someone has nothing to say for three weeks running, that's information. Ask better questions.</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Performance conversation</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">When the pattern is real and the 1:1s haven't fixed it. Direct, kind, specific, documented.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>PREPARE FIRST — write these down before the call\nSpecific observable examples (3, with dates):\n1. [date] — [what happened, factually, no adjectives]\n2. [date] — [what happened]\n3. [date] — [what happened]\n\nWhat I've already tried: [coaching, tools, clarification — and when]\nWhat good looks like: [specific and measurable]\nIs this a can't or a won't? [Skill gap, unclear expectation, resource problem, or motivation?]\n\nTHE CONVERSATION\nOpen — direct, no small talk warm-up. They'll know something's coming and the padding makes it worse.\n\"I want to talk about [area]. I've got some concerns and I want to understand what's happening.\"\n\nEvidence — facts, no adjectives.\n\"On [date], [what happened]. On [date], [what happened]. The pattern I'm seeing is [X].\"\n\nThen STOP and ask.\n\"What's your read on it?\"\n[Listen fully. Do not interrupt. The answer often changes what should happen next.]\n\nAgree the standard.\n\"What I need is [specific, measurable]. Is that achievable?\"\n\nAgree the support.\n\"What do you need from me to get there?\"\n\nAgree the timeline and the consequence.\n\"Let's check in on [date]. If we're not seeing [specific change] by then, we'll need to talk about whether this role is right.\"\n\nFOLLOW UP IN WRITING, SAME DAY\n\"Following up on our conversation. To make sure we're aligned:\n• The concern: [X]\n• What good looks like: [specific]\n• What I'm doing to support: [Y]\n• Review date: [date]\nAnything I've got wrong here, tell me.\"\n\n⚠ Never have this conversation for the first time in writing.\n⚠ Never have it in front of anyone else.\n⚠ Never let someone be surprised by it — if they're shocked, you failed at the 1:1s.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write your one-to-one agenda template, then draft real feedback for two situations: a small repeated error and a missed deadline that hurt a client.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A meeting template plus two feedback scripts using observation, effect, and instruction.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 45 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The template puts their items before yours</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Both scripts name a specific instance with a date</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Both state the effect explicitly</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Both end with a question, not a warning</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Neither uses the word disappointed</span></label></li></ul></div>"},{"n":7,"title":"The operating rhythm","outcome":"You can install a weekly and monthly cadence that makes the business predictable without adding meetings nobody wants.","badges":["Workflow","2 templates"],"minutes":28,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A rhythm is a small number of fixed events with fixed agendas. Its purpose is to make sure nothing important depends on someone remembering.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The minimum viable rhythm: a 15-minute Monday planning note, a mid-week unblock pass, a Friday scorecard and report, and a monthly review of one process.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Written beats live for distributed teams. A posted Monday note that people read on their own schedule outperforms a call three people attend half-awake.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Every recurring meeting needs a standing agenda and a decision log. If a meeting produces no decisions two weeks running, kill it.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The decision log is the artefact that makes you senior: what was decided, by whom, on what date, and what changed as a result. It ends the \"I thought we agreed\" cycle permanently.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Protect the rhythm during chaos. The weeks you skip the report are exactly the weeks the founder most needs to see the numbers.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Wilder and Co, the whole rhythm on one page</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Monday 8am: ops lead posts the week note in the general channel. Priorities, who owns what, anything at risk. Nobody meets.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Wednesday: unblock pass. Ops lead reviews every stalled card and either resolves it or escalates with a named decision needed.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Thursday: 20-minute one-to-ones with each of the two VAs.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Friday 9am: scorecard and report to the founder, five metrics, one decision request.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Friday 4pm: five-minute team retro in writing. One thing that worked, one thing that did not.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">First Monday of the month: one process reviewed against its SOP, updated, review date reset.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Quarterly: rate and scope review with the client, diarised at the start of the quarter.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Total live meeting time per week: 40 minutes.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Forty minutes of meetings a week and the business becomes legible. Most teams have five times the meetings and none of the artefacts.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">The operating rhythm</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Set it up once. Then protect it like it's the product, because it is.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Daily: async standup in writing</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Three lines per person in a channel: doing today, blocked on, needs someone. No meeting. Takes each person two minutes.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Weekly: 30-minute team meeting, scorecard first</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Numbers, then blockers, then decisions. Not status updates — those are already written down. If it's just status, cancel it.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Weekly: 1:1 with everyone who reports to you</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Non-negotiable, never cancelled. Everything you'd otherwise find out too late surfaces here.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Monthly: review the numbers properly and pick ONE thing</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Two hours. What moved, what didn't, and one process to fix next month. One. Ops teams fail by trying to fix five things badly.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Quarterly: step back and ask what should stop</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The question nobody asks. Which meeting, report or process has outlived its reason? Removing things is as valuable as adding them.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Protect it when things get busy</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The rhythm is what stops busy becoming chaos. Cancelling the weekly because the week is hectic is like removing the brakes because you're going fast.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Adding meetings without ever removing any. Every recurring meeting should have to justify itself quarterly, and you should personally kill at least one a quarter.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Async daily standup</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Posted in a channel by a set time. Replaces a 15-minute daily call across timezones, which for a PH-based team is worth a great deal.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[Post in #standup by [time] daily. Three lines. Under 60 seconds to write.]\n\n**[Your name] — [date]**\n📌 Today: [the 1–3 things you're actually doing. Not everything on your list.]\n🚧 Blocked: [what you're waiting on and who from. Write \"nothing\" if nothing.]\n🙋 Need: [anything you need from someone specific, with a deadline. \"Nothing\" is fine.]\n\nEXAMPLE\n**Maria — Mar 4**\n📌 Today: Peterson onboarding docs, invoice run, chase the 3 overdue accounts\n🚧 Blocked: waiting on Ben for the updated pricing sheet since Friday\n🙋 Need: @Ben pricing sheet by 2pm or the invoice run slips to tomorrow\n\nRULES THAT MAKE THIS WORK\n• Post by the deadline even if it's a light day\n• Blocked means blocked — name the person, don't be vague\n• If you're blocked two days running on the same thing, escalate to me, don't just repost it\n• Read the others'. Half the value is people unblocking each other without me.\n• No replies in the thread unless you're unblocking someone\n\nWHY WRITTEN, NOT A CALL\n• Works across timezones with no 6am meetings\n• Searchable — \"when did that start being a problem?\" has an answer\n• Two minutes to write, thirty seconds to read\n• Introverts communicate better in writing and you get more honest blockers</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Weekly team meeting agenda</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">30 minutes, hard stop. If it regularly finishes early, that's a success, not a waste.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>WEEKLY — [date] — 30 min, hard stop\n\n1. SCORECARD (5 min)\n   The five numbers on screen. Only discuss the red ones.\n   For each red: cause, action, owner, date. No debating the number itself.\n\n2. BLOCKERS (10 min)\n   Round the room: anything stuck that the standup didn't resolve?\n   Rule: name the blocker and who can unblock it. Solving happens after the meeting,\n   with the two people who need to be there — not with everyone watching.\n\n3. DECISIONS NEEDED (10 min)\n   Things that genuinely need a group decision.\n   Anyone bringing one must bring: the options, a recommendation, and a deadline.\n   No \"what does everyone think?\" without a proposal attached.\n\n4. THIS WEEK'S PRIORITY (3 min)\n   The ONE thing that matters most this week. Everyone says it out loud.\n\n5. ANYTHING ELSE (2 min)\n\nNOT IN THIS MEETING\n• Status updates — those are in the standup and the tracker\n• Anything involving only two people\n• Anything that needs 45 minutes of context\n• Performance feedback — that's 1:1, always\n\nAFTER (within 2 hrs)\nPost the decision log to the channel:\n• Decided: [what], because [why]\n• Actions: [what] — [who] — [by when]\n• Parked: [what], revisit [when]\n\nIF THIS MEETING IS JUST PEOPLE READING OUT THEIR WEEK, CANCEL IT.\nReplace it with the written standup and give everyone 30 minutes back.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Design the operating rhythm for your business, then write the Monday note and the Friday report templates.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page rhythm plus two reusable templates.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 50 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Total live meeting time is under 90 minutes a week</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Every recurring event has a fixed agenda</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">There is a decision log with a location and an owner</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">At least one event is written rather than live</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The monthly process review is on a real date</span></label></li></ul></div>"},{"n":8,"title":"Automation without becoming the risk","outcome":"You can automate the obvious wins and document them so the business does not quietly become dependent on your memory.","badges":["Workflow","Red/green flags","1 template"],"minutes":26,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Automate only what is already documented and stable. Automating a broken process just makes it fail faster and more confusingly.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Start with the three universal wins: intake to task, notification of a stalled item, and data landing in one sheet instead of three inboxes.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Every automation gets a register entry: what it does, what triggers it, who owns it, where it breaks, and how to turn it off.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Build a failure alarm. Silent automations that stop working are worse than no automation, because everybody assumes it is still running.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">AI tools are fine for drafting, summarising and first-pass classification. They are not fine for anything that sends money, deletes data, or speaks to a client unreviewed.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Being the only person who understands the stack feels like security and is actually a cap on your career. You cannot be promoted out of a role nobody else can run.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Automation register, three entries</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">1. Enquiry form to task. Trigger: Typeform submission. Action: creates a card in the Intake list with a 2-hour due time and pings the support channel. Owner: ops lead. Breaks if: the form fields are renamed. Off switch: pause the zap, then reply manually from the shared inbox.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">2. Stalled card alert. Trigger: daily 7am. Action: posts any card untouched for 3 days to the ops channel with the owner tagged. Owner: ops lead. Breaks if: the board list names change. Off switch: pause; fall back to the Wednesday manual unblock pass.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">3. Review request. Trigger: card moves to Delivered. Action: sends the review email after 48 hours. Owner: support VA. Breaks if: the client email field is empty. Off switch: pause; the support VA sends manually from the template.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Monthly check: confirm all three fired at least once, in the first-Monday process review.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Every entry has a manual fallback. That single column is the difference between automation as leverage and automation as a hidden liability.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Automating something safely</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A process that's repetitive, high-volume, and — crucially — already stable.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Only automate a process that already works</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Automating a broken process makes it break faster and more consistently. Fix it manually first, run it for a month, then automate.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Calculate whether it's worth it, honestly</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Time saved per week × 52, against build time plus ongoing maintenance. Plenty of clever automations save 20 minutes a week and cost an hour a month to maintain.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Build it on company accounts, never yours</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Company Zapier, company Google account, company API keys. Anything on your personal login is a resignation-day disaster.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Add failure alerts before you add features</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The very first thing after 'it works' is 'it tells someone when it doesn't'. Route it to a channel a human reads.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Document the flow AND the manual fallback</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A diagram of what triggers what, plus written instructions for doing it by hand. The fallback is what makes the automation safe.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Have someone else run it once, from the docs</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">If only you can fix it, you've built a liability. This step is what converts it into an asset.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Automating the interesting thing rather than the frequent thing. The boring daily task that takes 20 minutes is worth 87 hours a year; the clever quarterly one is worth four.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">You build an automation that saves 5 hours a week</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Building it in your personal Zapier account, on your login, with no documentation, and telling nobody how it works.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">You've become a single point of failure and made the business dependent on your personal account. When you're sick, on leave, or gone, it breaks silently and nobody knows why. That's not job security — it's a liability with your name on it.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Built on a company account, documented in the SOP library with a diagram of what triggers what, with an alert if it fails, and a written manual fallback for when it does. Then walk one other person through it.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">The automation is only valuable if it survives you. Building things only you understand feels like security and is actually the thing that stops you being promoted — you can't be moved up if you can't be replaced.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">An automation fails silently for two weeks</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Discovering it when a client complains, then fixing it quietly and not mentioning it.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Silent failure is the specific danger of automation — manual processes fail loudly because a human notices. Automated ones fail invisibly and the damage compounds. Hiding it means it'll happen again.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Every automation gets a failure alert to a channel from day one. When one does fail: tell people, quantify the impact, fix it, and add the check that would have caught it sooner.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Automation without monitoring isn't automation, it's a delayed problem. The alert costs ten minutes to set up and it's the difference between a hiccup and an incident.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Automation register</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Every automation in the business, in one table. When something behaves strangely, this is the first place to look.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><div class=\"p-3.5 space-y-3\"><div class=\"overflow-x-auto rounded-lg border border-line\"><table class=\"w-full min-w-[600px] text-[0.8125rem]\"><thead><tr class=\"bg-paper-2\"><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">#</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">What it does</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Trigger</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Tool</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Account</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Owner</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Alerts to</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Manual fallback</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Last checked</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">01</td><td class=\"px-3 py-2.5 text-ink-2\">Form submission → CRM + Slack alert</td><td class=\"px-3 py-2.5 text-ink-2\">Typeform submit</td><td class=\"px-3 py-2.5 text-ink-2\">Zapier</td><td class=\"px-3 py-2.5 text-ink-2\">company@</td><td class=\"px-3 py-2.5 text-ink-2\">Me</td><td class=\"px-3 py-2.5 text-ink-2\">#ops-alerts</td><td class=\"px-3 py-2.5 text-ink-2\">SOP 14</td><td class=\"px-3 py-2.5 text-ink-2\">Mar 4</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">02</td><td class=\"px-3 py-2.5 text-ink-2\">Invoice reminders at 7/14/21 days</td><td class=\"px-3 py-2.5 text-ink-2\">Schedule</td><td class=\"px-3 py-2.5 text-ink-2\">Xero</td><td class=\"px-3 py-2.5 text-ink-2\">company@</td><td class=\"px-3 py-2.5 text-ink-2\">Ben</td><td class=\"px-3 py-2.5 text-ink-2\">#finance</td><td class=\"px-3 py-2.5 text-ink-2\">SOP 09</td><td class=\"px-3 py-2.5 text-ink-2\">Mar 1</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">03</td><td class=\"px-3 py-2.5 text-ink-2\">Weekly scorecard pull</td><td class=\"px-3 py-2.5 text-ink-2\">Mon 6am</td><td class=\"px-3 py-2.5 text-ink-2\">Sheets script</td><td class=\"px-3 py-2.5 text-ink-2\">company@</td><td class=\"px-3 py-2.5 text-ink-2\">Me</td><td class=\"px-3 py-2.5 text-ink-2\">#ops-alerts</td><td class=\"px-3 py-2.5 text-ink-2\">Manual pull, 20 min</td><td class=\"px-3 py-2.5 text-ink-2\">Feb 26</td></tr></tbody></table></div><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">EVERY ROW MUST HAVE\n• A company account, never a personal one\n• A named human owner\n• An alert destination that a person actually reads\n• A documented manual fallback\n• A last-checked date — review everything quarterly\n\nBEFORE YOU BUILD, ANSWER THESE\n1. How many minutes/week does this save? [n] → × 52 = [n] hrs/year\n2. How long to build? [n] hrs. Maintenance? [n] hrs/year\n3. Worth it? [Y/N — if the payback is over 6 months, probably not]\n4. What happens if it fails silently for a week? [If the answer is \"serious\", build the alert first]\n5. Can someone else fix it from the docs? [If no, it's not finished]\n\n⚠ NEVER AUTOMATE\n• Anything that sends money\n• Anything that emails a customer without a human check, unless volume makes that impossible\n• Anything touching a legal deadline\n• A process that changes monthly — you'll spend more time maintaining it than doing it\n• A process nobody has documented — you don't understand it well enough yet</pre></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build one real automation for your mapped process and write the register entry for it, including the failure mode and the manual fallback.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A working zap or scenario plus a register entry.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 60 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The underlying process was documented before you automated it</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The register entry names what breaks it</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">There is a manual fallback anyone could follow</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">You tested the failure case, not just the happy path</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Someone other than you could turn it off</span></label></li></ul></div>"},{"n":9,"title":"Managing upward","outcome":"You can report to a founder in a way that earns you decision rights, and you can say no without sounding like you are refusing work.","badges":["Red/green flags","2 templates"],"minutes":28,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Founders are not avoiding your questions, they are drowning. Your job is to reduce the number of decisions they have to make, not to route more of them upward.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Bring a recommendation, never a menu of open questions. \"Here is the issue, here are two options, I recommend B, tell me by Wednesday if you disagree\" is the whole format.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Ask for decision rights explicitly and in small increments. \"Can I approve anything under $2,000 without asking?\" gets a yes far more often than a vague request for more autonomy.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use the silence rule for low-risk items: \"unless you say otherwise by Thursday, I will proceed with B.\" It respects their time and it moves work.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Saying no is a scoping conversation. \"Yes, and that pushes the invoicing project to next month, or I can bring in five hours of contractor time. Which?\" Trade-offs, not refusals.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Report bad news early and with a plan attached. The founders who stop trusting an ops lead are almost always the ones who found out late.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Escalation, weak and strong</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Hi, the Kaplan project is behind and I'm not sure what to do. The contractor hasn't replied and the client is asking. Let me know how you want to handle it?\"</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Kaplan is 4 days behind. The contractor has not replied since Monday and the client emailed this morning.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"What I have done: called and emailed the contractor, and set a Wednesday 5pm cutoff. I have told the client we will confirm a revised date by Thursday, without blaming anyone.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"Two options. A: hold until Wednesday and hope. B: brief the backup contractor now, which costs about $180 extra and lands us one day late instead of five.\"</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">\"I recommend B, because the reputational cost with Kaplan outweighs $180. Unless you say otherwise by Wednesday noon, I will proceed with B.\"</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The second one requires roughly ten seconds of the founder's attention. Do that for six months and the decision rights start arriving without you asking.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">The founder keeps changing priorities mid-week</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Silently absorbing it, reshuffling the team every time, and quietly burning out while the team loses trust in every plan you announce.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">You're protecting them from the consequences of their own behaviour, which guarantees it continues. Meanwhile your team learns that your plans don't mean anything, and that costs you more than the churn does.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">\"Happy to switch to the new thing — I just need to know what drops. Right now the team's on A, B and C. If D becomes the priority, which of those moves to next month? I'd suggest C.\" Every single time, calmly, without irritation.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">You're not refusing, you're making the tradeoff visible. Founders change priorities because it feels free. Making the cost explicit — every time, without emotion — is the only thing that changes the behaviour.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">You disagree with a decision the founder has made</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Going along with it while telling the team you disagree. Or arguing about it repeatedly after it's been decided.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">The first undermines the decision and your own authority simultaneously — the team now knows you don't back your own instructions. The second makes you exhausting to work with and gets you left out of the next conversation.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Argue hard once, in private, with evidence. Then: \"I still think it's the wrong call and I've said why. It's your decision and I'll run it properly.\" Then genuinely run it properly, and diarise a date to review the outcome.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Disagree and commit. You get one strong argument, made privately with your reasoning on the record. If you're proved right later, the record speaks for itself and you never have to say I told you so.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The weekly note to the founder</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Same shape, same day, every week. This single document is why ops leads get trusted with more.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[Week ending date]\n\nTHE NUMBERS\n[Metric]: [n] vs target [n] 🟢\n[Metric]: [n] vs target [n] 🔴\n[Metric]: [n] vs target [n] 🟢\n\n🔴 [The red one]: [cause in one line]. Doing: [action, owner, date].\n\nSHIPPED THIS WEEK\n• [Thing]\n• [Thing]\n\nDECISIONS I MADE ON YOUR BEHALF\n• [What, and the reasoning in one line. So you can veto it now rather than be surprised later.]\n\nNEEDS YOU — [n] things\n1. [Decision needed]. Options: [A] or [B]. I'd pick [A] because [reason]. Need by [date].\n2. [Thing only you can do]. By [date].\n\nRISKS I'M WATCHING\n• [Thing that might become a problem, and what would trigger me escalating it]\n\nNEXT WEEK\nPriority: [the one thing]\nAlso: [2–3 things]\n\nWHAT I'D LIKE MORE OF\n[Occasional. Budget, headcount, decision authority, your time. Ask specifically, with a reason.]\n\nRULES\n• Never more than one page\n• Always include the bad news, first, in the numbers section\n• \"Needs you\" capped at three items — more than that and you're delegating upward\n• Send it the same day every week even in a quiet week. The consistency is the point.</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Escalating without sounding like a complaint</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">When something genuinely needs the founder to change something. Frame as a business problem, never a personal grievance.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>THE STRUCTURE\n1. The business impact (not your feelings)\n2. The cause (specific and factual)\n3. What you've already tried\n4. Two options, with a recommendation\n5. What you need from them, and by when\n\nEXAMPLE — priority churn\n\"Onboarding time has gone from 3 to 7 days over the last month, and two clients have mentioned it.\n\nThe cause is that we've changed the team's weekly priority mid-week four times since [date]. Each switch costs about a day of re-planning and the onboarding work is what keeps getting paused.\n\nI've tried absorbing it by reshuffling rather than dropping anything, and that's why it's showing up as slower delivery rather than as things not getting done.\n\nTwo options:\n1. We hold priorities for a full week and anything new goes into the next week's plan unless it's genuinely on fire. I'd need you to agree what counts as on fire.\n2. We keep switching, and I formally drop [specific work] so there's capacity for it.\n\nI'd recommend 1. Can we agree which by Friday?\"\n\nEXAMPLE — asking for headcount\n\"We're at [n]% capacity and turning away [specific thing] as a result.\n\nCause: volume is up [n]% since [date] with the same three people.\n\nI've already automated [X] which bought back [n] hrs/week, and I've dropped [Y] entirely. That's the available slack gone.\n\nOptions:\n1. Hire a [role] at ~$[n]/mo. Pays for itself if it lets us take on [n] more [units].\n2. Stop doing [specific thing], which frees [n] hrs but costs us [consequence].\n\nI'd recommend 1. Happy to have the job post ready by [date] if you're open to it.\"\n\nNEVER\n• \"The team is stressed\" without a number attached\n• \"This isn't fair\"\n• Escalating without having tried something first\n• Bringing a problem with no options\n• Doing it in front of other people</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Rewrite three escalations you have actually sent into the issue, action taken, options, recommendation, deadline format. Then write your decision rights request.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: Three rewritten escalations plus a one-paragraph request for three specific decision rights.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 45 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Each escalation states what you already did before asking</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Each has exactly two options and a recommendation</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Each has a deadline with a default action</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The decision rights request names thresholds, not feelings</span></label></li></ul></div>"},{"n":10,"title":"Capstone: the 90-day plan and pricing yourself","outcome":"You have a 90-day operations plan you could present tomorrow, and a defensible number for the role.","badges":["Workflow","Rates","2 templates"],"minutes":45,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The pitch is not \"promote me\". It is a plan for their business with you in it, and a price that is smaller than the leaks it closes.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Structure the 90 days as diagnose, stabilise, systematise. Days 1 to 30 map and measure, 31 to 60 fix the top three leaks and document them, 61 to 90 delegate and hand over the running of them.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Price against the value, then sanity-check against the market. Ops leadership is not on the general VA ladder, because you are being paid for judgment and for other people's output.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Move to a monthly retainer rather than hourly. Once you are paid for outcomes, hourly billing actively punishes you for building things that save time.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Show the arithmetic. \"Two unbilled projects last quarter was about $9,000, the approval bottleneck cost eleven delivery days, and reviews went from zero to five a month\" is a stronger argument than any adjective.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">If the current client will not fund the role, the plan is still yours. It is now the portfolio piece that gets you hired somewhere that will.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The 90-day plan, one page</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Days 1 to 30, diagnose: process map lead to cash, five-metric baseline, interview all 12 staff, rank leaks by cost. Deliverable: the map, the scorecard with baselines, and a ranked leak list.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Days 31 to 60, stabilise: close the top three leaks. Invoicing run documented and owned, shared inbox given an owner with a 2-hour target, approval threshold delegated at $2,000. Deliverable: three SOPs, live scorecard, first four weekly reports.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Days 61 to 90, systematise: hire one support VA against a scorecard, run a paid test task, onboard against SOPs, install the operating rhythm. Deliverable: a trained hire, the rhythm running, an automation register with three entries.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">What it is worth: unbilled work recovered, roughly $9,000 a quarter. Approval delays cut from 3 days to same-day on most jobs. Founder time returned, about 6 hours a week.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">What it costs: $2,600 a month retainer, 30 hours a week, plus one support VA at about $600 a month that I hire and manage.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Review: at day 90 against the scorecard, in writing, either of us can adjust.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Every number in the cost line is smaller than a number in the value line. That is the entire pitch, and it is arithmetic rather than persuasion.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">The 90-day plan you present to get the job</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Final interview for an ops role, or pitching yourself internally for a promotion.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Days 1–30: understand, change nothing</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Process interviews with everyone, map the money path, find the single points of failure. Present findings, not proposals.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Day 30: present the diagnosis and get agreement</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">\"Here's what I found, here's what I think matters most, here's what I'd do first.\" Get them to agree on the problem before you fix anything.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Days 31–60: fix ONE thing visibly</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The highest-pain, most-visible process. One clear win builds the credit you'll need for the harder changes.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Days 31–60: stand up the scorecard and the rhythm</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Five metrics, weekly meeting, async standup, 1:1s. Cheap to build, and it's the infrastructure everything else runs on.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Days 61–90: document and delegate</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">SOPs for the top five processes, each with an owner who isn't you. This is what proves you're an ops lead rather than a very good VA.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Day 90: review against the numbers, and set the next 90</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">What moved, what didn't, what you were wrong about. Being publicly wrong about one thing makes the rest credible.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Promising transformation in 90 days. Promise a diagnosis, one visible fix, and a working rhythm. Under-promise here — you're being hired for judgment, and wild promises are evidence against having any.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Pricing yourself as an ops lead</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Four different shapes, four different economics. Most people default to the first without knowing the others exist.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width: 38rem;\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Employed ops lead (one company, full-time)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$16–30</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$2,600–4,800</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Most stable, lowest ceiling. Best if you want to go deep and learn.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Fractional ops (2–3 clients, 10–15 hrs each)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$30–60</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,500–3,000 per client</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Highest earnings, most variety, most instability. Do this after in-house experience.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Ops project work</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">Fixed fee</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,500–6,000 per project</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">SOP library build, systems migration, ops audit. Great way to test a client.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Ops audit (the door-opener)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">10–20 hrs</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$500–2,000 one-off</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Sell this first. It's a low-risk yes and it frequently becomes a retainer.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Retainer + build fee</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">Both</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$2,000 build, then $1,500/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Charge to build the system, then to run it. The best structure of the lot.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Fractional is the highest-earning shape available to a Filipino ops professional — three clients at $2,000/month is $6,000/month, which is above many in-house ops salaries in the US.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The 90-day plan (present this in the final interview)</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Bring this unprompted to a final-stage ops interview. Almost nobody does, and it changes the conversation from 'can you do this' to 'when can you start'.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>90-DAY PLAN — [role] at [company]\n[Your name] | [date]\n\nWHAT I THINK IS TRUE (from our conversations)\n• [Something specific they told you about the business]\n• [A problem they named]\n• [Something you inferred — flag it as an assumption]\n\nI could be wrong on any of these. The first 30 days is about finding out.\n\nDAYS 1–30 — UNDERSTAND\n• 30-min process interview with every person\n• Map the path from lead to cash, end to end\n• Identify single points of failure (which processes live in one head)\n• Baseline the numbers, even roughly\nDeliverable, day 30: a findings doc and a prioritised list. No changes made yet.\n\nDAYS 31–60 — ONE VISIBLE FIX + THE RHYTHM\n• Fix the highest-pain process — likely [your guess], but the data decides\n• Stand up a 5-metric scorecard\n• Start the operating rhythm: async standup, weekly meeting, 1:1s\nDeliverable, day 60: one process measurably improved, and a scorecard you can read weekly.\n\nDAYS 61–90 — DOCUMENT AND HAND OVER\n• SOPs for the top 5 processes, each with a named owner who isn't me\n• Automation register, if anything's worth automating\n• Second process improvement\nDeliverable, day 90: a written review of what moved, what didn't, and the next 90 days.\n\nWHAT I'D NEED FROM YOU\n• [n] hours a week of your time in the first month\n• Authority to [specific — change process X, talk to clients, spend up to $Y]\n• Agreement that I don't change anything major in the first 30 days\n\nWHAT I WON'T PROMISE\nI won't promise to transform anything in 90 days. Ops changes compound slowly and\nanyone promising a turnaround in a quarter hasn't done it. What I will promise is\nthat by day 90 you'll know exactly what's broken, one thing will be measurably\nbetter, and you'll have a weekly view of the business you don't have now.</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Ops audit proposal (how to sell fractional work)</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">The easiest ops thing to sell. Low commitment for them, and roughly half convert to a retainer.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>OPERATIONS AUDIT — [company]\nPrepared for [name] | [date]\n\nWHAT I HEARD\n[2–3 sentences quoting their own words back. \"You said you're the bottleneck on\neverything and you can't take a week off without things breaking.\"]\n\nWHAT THIS IS\nTwo weeks, roughly [n] hours, to answer three questions:\n1. Where does time actually go in this business?\n2. What breaks when a specific person is unavailable?\n3. What are the three highest-value things to fix, in order?\n\nHOW\nWeek 1: process interviews with everyone, tool audit, map the lead-to-cash path\nWeek 2: analysis, prioritisation, and writing it up\n\nWHAT YOU GET\n• A process map of how the business actually runs (not how it's supposed to)\n• A single-point-of-failure register — the honest list of what depends on one person\n• A prioritised fix list, scored by impact and effort\n• A recommended 5-metric scorecard\n• A 90-day roadmap, costed\n• 60-minute walkthrough call\n\nINVESTMENT\n$[n], 50% up front, 50% on delivery.\n\nWHAT HAPPENS AFTER\nThree options, and I'm genuinely fine with any:\n1. You take the roadmap and run it yourself. It's yours, in full.\n2. I execute it — [n] hrs/week at $[n]/month.\n3. We do nothing. You've still got the map.\n\nWHAT I WON'T DO\nI won't tell you to buy software you don't need, and I won't recommend a\nrestructure in week two. Most ops problems are documentation and rhythm problems,\nand those are cheap to fix.\n\nAvailable to start [date].</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write the full 90-day plan for a real or fictional business, including the value arithmetic and your retainer price. Then record a five-minute Loom presenting it.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page plan plus a Loom you would genuinely send to a founder.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 90 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Each 30-day phase has named deliverables</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The value side has at least three quantified items</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">Your price is a monthly retainer with stated hours and scope</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">There is a review date and an exit for both sides</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input class=\"sr-only\" type=\"checkbox\"><span class=\"\">The Loom is under six minutes and you did not read it word for word</span></label></li></ul></div>"}],"quiz":[{"q":"Which of these is written as an outcome rather than a task?","options":["Manage the project board daily","Every new client is fully live within 5 business days of signing","Help the team with anything else needed","Follow up with contractors regularly"],"answer":1,"explain":"It is countable, dated, and someone outside the room could grade it. The other three describe effort, which is exactly what keeps people paid hourly."},{"q":"You map lead to cash and find seven leaks. Which do you fix first?","options":["The one the team complains about most","The easiest one, for a quick win","The most expensive one, estimated in money","The one closest to the founder"],"answer":2,"explain":"Rank by cost. In the Wilder scenario the loudest complaint was the slow inbox, but two projects going entirely unbilled was worth thousands and nobody had ever mentioned it."},{"q":"What makes an SOP library stay alive rather than rot?","options":["Writing them all in one focused week","Storing them in a well-organised folder","An owner and a review date on every document, linked from the task itself","Making them as detailed as possible"],"answer":2,"explain":"Ownership and a review date keep them true, and linking from the task keeps them read. Documentation written in one heroic week and filed neatly is the classic dead library."},{"q":"A capable team member who used to hit deadlines has missed three in two weeks. First move?","options":["Give a written warning","Diagnose whether it is will or skill, and ask what changed","Take the work back and do it yourself","Add more check-ins to the calendar"],"answer":1,"explain":"The change in pattern is the signal. A previously reliable person usually has a blocker, a priority conflict, or something outside work. Warnings and surveillance both fail if the cause is a blocker you could have removed."},{"q":"How should you escalate a project running four days late?","options":["Ask the founder how they want to handle it","Say nothing until you know the outcome","State the issue, what you already did, two options, your recommendation, and a deadline with a default","Fix it yourself overnight and mention it afterwards"],"answer":2,"explain":"That format costs the founder about ten seconds and returns a decision. Handing them an open question adds to the pile you were hired to reduce."},{"q":"You are about to automate the monthly invoicing run. What must be true first?","options":["You have a Zapier paid plan","The process is already documented and stable, and you have written the manual fallback","The founder has approved the tool","You have tested the happy path"],"answer":1,"explain":"Automating an undocumented or unstable process just makes it fail faster and more mysteriously. The register entry with a failure mode and a manual fallback is what turns automation into leverage instead of a hidden liability."}],"glossary":[{"term":"SOP","def":"Standard operating procedure. Numbered steps with an owner, a review date, and a failure branch."},{"term":"Scorecard","def":"A small set of metrics with baselines, targets, and named owners, reviewed on a fixed cadence."},{"term":"Operating rhythm","def":"The fixed weekly and monthly events that make a business predictable without extra meetings."},{"term":"Decision log","def":"What was decided, by whom, when, and what changed. Ends the \"I thought we agreed\" loop permanently."},{"term":"RACI","def":"Responsible, Accountable, Consulted, Informed. A one-line way to stop two people owning the same thing."},{"term":"Handoff","def":"The moment work passes between people. Statistically where most of it dies."},{"term":"Bottleneck","def":"The step that limits total throughput. Improving anything else first is decoration."},{"term":"Single point of failure","def":"A person or system whose absence stops the work. Usually the founder, sometimes you."},{"term":"OBM","def":"Online business manager. An ops lead for small online businesses, typically two or three clients on retainer."},{"term":"Integrator","def":"The person who turns a founder's ideas into a plan with owners and dates. Same job, different vocabulary."},{"term":"Role scorecard","def":"The three measurable outcomes a seat owns. Written before hiring, used for reviews after."},{"term":"Paid test task","def":"A short, scoped, paid piece of real work used to assess a candidate. The only reliable predictor there is."},{"term":"Will vs skill","def":"The diagnostic before correcting someone. Motivation problems and training problems need opposite responses."},{"term":"Decision rights","def":"Written authority to decide up to a stated threshold without asking. Request them in small increments."},{"term":"Concentration risk","def":"How much of your income sits with one client. Above half and you have a boss, not a client."}]} as DeepCourse;

export default course;
